146	    /** 撤销授权；返回受影响行数，0 表示不存在或已撤销。 */
147	    public int revokeGrant(long id, String revokeRequestId, long revokedAtMs) {
148	        return jdbc.update("UPDATE playout_grant SET revoked = 1, revoke_request_id = ?, revoked_at_ms = ?"
