227	        KeyHolder keyHolder = new GeneratedKeyHolder();
228	        jdbc.update(con -> {
229	            PreparedStatement ps = con.prepareStatement(
230	                    "INSERT INTO playout_publication"
231	                            + " (channel_id, business_day, published_version, draft_version, created_at_ms)"
232	                            + " VALUES (?, ?, ?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
233	            ps.setString(1, channelId);
234	            ps.setDate(2, Date.valueOf(businessDay));
235	            ps.setLong(3, publishedVersion);
236	            ps.setLong(4, draftVersion);
237	            ps.setLong(5, createdAtMs);
238	            return ps;
239	        }, keyHolder);
240	        return keyHolder.getKey().longValue();
