262	        return jdbc.query("SELECT id, publication_id, segment_id, asset_id, grant_id, start_ms, end_ms"
263	                        + " FROM playout_publication_segment"
264	                        + " WHERE publication_id = ? AND start_ms <= ? AND end_ms > ?"
265	                        + " ORDER BY start_ms LIMIT 1",
266	                PUBLICATION_SEGMENT_MAPPER, publicationId, atMs, atMs).stream().findFirst();
267	    }
268	
269	    // ---------- 幂等请求记录 ----------
270	
271	    /** 按请求 ID 查询并加行锁，用于去重判定。 */
272	    public Optional<RequestRow> findRequestForUpdate(String requestId) {
273	        return jdbc.query("SELECT request_id, operation, params_hash, response_body"
274	                        + " FROM playout_request WHERE request_id = ? FOR UPDATE",
275	                REQUEST_MAPPER, requestId).stream().findFirst();
276	    }
277	
278	    public void insertRequest(String requestId, String operation, String paramsHash, long createdAtMs) {
279	        jdbc.update("INSERT INTO playout_request (request_id, operation, params_hash, created_at_ms)"
280	                + " VALUES (?, ?, ?, ?)", requestId, operation, paramsHash, createdAtMs);
281	    }
282	
283	    public void completeRequest(String requestId, String responseBody) {
284	        jdbc.update("UPDATE playout_request SET response_body = ? WHERE request_id = ?",
285	                responseBody, requestId);
286	    }
287	
288	    /** 判断是否为唯一键冲突（草稿首建、发布版本、请求 ID 等并发场景）。 */
289	    public static boolean isDuplicateKey(RuntimeException ex) {
290	        return ex instanceof DuplicateKeyException;
291	    }
292	}
