142	    // ---------- 草稿 ----------
143	
144	    /** 整份替换草稿；携带 expectedDraftVersion（0 表示首次创建），版本不符返回 409 且不改写原草稿。 */
145	    @Transactional
146	    public DraftResponse replaceDraft(String channelId, LocalDate businessDay,
147	                                      ReplaceDraftRequest request) {
148	        repo.findChannel(channelId)
149	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
150	
151	        String hash = sha256(OP_REPLACE_DRAFT + "|" + channelId + "|" + businessDay
152	                + "|" + request.expectedDraftVersion() + "|" + canonicalSegments(request.segments()));
153	        return idempotent(request.requestId(), OP_REPLACE_DRAFT, hash, DraftResponse.class, () -> {
154	            List<ValidatedSegment> segments = validateSegments(channelId, businessDay, request.segments());
155	            long newVersion;
156	            if (request.expectedDraftVersion() == 0) {
157	                try {
158	                    repo.insertDraft(channelId, businessDay, nowMs());
159	                } catch (DuplicateKeyException e) {
160	                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
161	                            "草稿已存在，expectedDraftVersion 不能为 0");
162	                }
163	                newVersion = 1;
164	            } else {
165	                int updated = repo.bumpDraftVersion(channelId, businessDay,
166	                        request.expectedDraftVersion(), nowMs());
167	                if (updated == 0) {
168	                    throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
169	                            "草稿版本不符，期望 " + request.expectedDraftVersion());
170	                }
171	                newVersion = request.expectedDraftVersion() + 1;
172	            }
173	            repo.deleteDraftSegments(channelId, businessDay);
174	            for (ValidatedSegment segment : segments) {
175	                repo.insertDraftSegment(segment.id(), channelId, businessDay,
176	                        segment.assetId(), segment.startMs(), segment.endMs());
177	            }
178	            return new DraftResponse(channelId, businessDay.toString(), newVersion,
179	                    segments.stream().map(ValidatedSegment::toResponse).toList());
180	        });
181	    }
182	
183	    // ---------- 发布 ----------
184	
185	    /**
186	     * 发布草稿：校验草稿版本与发布版本，逐片段加锁校验授权仍有效后原子生成只读快照。
187	     * 与授权撤销并发时按数据库提交顺序生效：撤销先提交则本方法因授权失效而 422 拒绝。
188	     */
189	    @Transactional
190	    public PublishResponse publish(String channelId, LocalDate businessDay, PublishRequest request) {
191	        repo.findChannel(channelId)
192	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
193	
194	        String hash = sha256(OP_PUBLISH + "|" + channelId + "|" + businessDay
195	                + "|" + request.draftVersion() + "|" + request.expectedPublishedVersion());
196	        return idempotent(request.requestId(), OP_PUBLISH, hash, PublishResponse.class, () -> {
197	            DraftRow draft = repo.findDraft(channelId, businessDay)
198	                    .orElseThrow(() -> ApiException.notFound("草稿不存在: " + channelId + " " + businessDay));
199	            List<SegmentRow> segments = repo.findDraftSegments(channelId, businessDay);
200	            if (draft.version() != request.draftVersion()) {
201	                throw ApiException.conflict("DRAFT_VERSION_CONFLICT",
202	                        "草稿版本不符，当前 " + draft.version());
203	            }
204	            long currentPublished = repo.currentPublishedVersion(channelId, businessDay);
205	            if (currentPublished != request.expectedPublishedVersion()) {
206	                throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
207	                        "发布版本冲突，当前 " + currentPublished);
208	            }
209	            List<Long> grantIds = new ArrayList<>();
210	            for (SegmentRow segment : segments) {
211	                GrantRow grant = selectCoveringGrantForUpdate(channelId, segment);
212	                grantIds.add(grant.id());
213	            }
214	            long newVersion = currentPublished + 1;
215	            long publicationId;
216	            try {
217	                publicationId = repo.insertPublication(channelId, businessDay,
218	                        newVersion, draft.version(), nowMs());
219	            } catch (DuplicateKeyException e) {
220	                throw ApiException.conflict("PUBLISHED_VERSION_CONFLICT",
221	                        "发布版本冲突，版本 " + newVersion + " 已存在");
222	            }
223	            for (int i = 0; i < segments.size(); i++) {
224	                SegmentRow segment = segments.get(i);
225	                repo.insertPublicationSegment(publicationId, segment.id(), segment.assetId(),
226	                        grantIds.get(i), segment.startMs(), segment.endMs());
227	            }
228	            return new PublishResponse(publicationId, channelId, businessDay.toString(),
229	                    newVersion, draft.version());
230	        });
231	    }
232	
233	    // ---------- 播出决定 ----------
234	
235	    /**
236	     * 按频道与时刻查询播出决定。命中有效片段返回节目素材；无已发布编排、空档或授权已撤销时
237	     * 返回保底素材及明确原因。撤销判定基于授权当前状态，不改写历史快照。
238	     */
239	    @Transactional(readOnly = true)
240	    public PlayoutDecisionResponse playoutDecision(String channelId, OffsetDateTime at) {
241	        var channel = repo.findChannel(channelId)
242	                .orElseThrow(() -> ApiException.notFound("频道不存在: " + channelId));
243	        long atMs = toMs(at);
244	        LocalDate businessDay = at.atZoneSameInstant(ZONE).toLocalDate();
245	
246	        Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
247	        if (publication.isEmpty()) {
248	            return fallback(channelId, at, channel.fallbackAssetId(),
249	                    FallbackReason.NO_PUBLISHED_SCHEDULE);
250	        }
251	        Optional<PublicationSegmentRow> segment =
252	                repo.findPublicationSegmentAt(publication.get().id(), atMs);
253	        if (segment.isEmpty()) {
254	            return fallback(channelId, at, channel.fallbackAssetId(),
255	                    FallbackReason.GAP);
256	        }
257	        PublicationSegmentRow hit = segment.get();
258	        GrantRow grant = repo.findGrant(hit.grantId())
259	                .orElseThrow(() -> ApiException.unprocessable("SNAPSHOT_INCOMPLETE",
260	                        "发布快照引用的授权不存在: " + hit.grantId()));
261	        if (grant.revoked()) {
262	            return new PlayoutDecisionResponse(channelId, at, channel.fallbackAssetId(),
263	                    DecisionSource.FALLBACK,
264	                    FallbackReason.GRANT_REVOKED,
265	                    publication.get().id(), hit.segmentId());
266	        }
267	        return new PlayoutDecisionResponse(channelId, at, hit.assetId(),
268	                DecisionSource.PROGRAM, null,
269	                publication.get().id(), hit.segmentId());
270	    }
271	
272	    // ---------- 内部方法 ----------
273	
274	    /** 校验并规范化草稿片段：非空、区间内、不跨日、不重叠、素材存在且被单条未撤销授权完整覆盖。 */
275	    private List<ValidatedSegment> validateSegments(String channelId, LocalDate businessDay,
276	                                                    List<SegmentInput> inputs) {
277	        long dayStartMs = businessDay.atStartOfDay(ZONE).toInstant().toEpochMilli();
278	        long dayEndMs = businessDay.plusDays(1).atStartOfDay(ZONE).toInstant().toEpochMilli();
279	
280	        List<ValidatedSegment> segments = new ArrayList<>();
281	        for (SegmentInput input : inputs) {
282	            if (input.start() == null || input.end() == null) {
283	                throw ApiException.badRequest("片段开始与结束时间不能为空");
284	            }
285	            if (input.assetId() == null || input.assetId().isBlank()) {
286	                throw ApiException.badRequest("片段素材 ID 不能为空");
287	            }
288	            long startMs = toMs(input.start());
289	            long endMs = toMs(input.end());
290	            if (endMs <= startMs) {
291	                throw ApiException.badRequest("片段结束时间必须大于开始时间");
292	            }
293	            if (startMs < dayStartMs || endMs > dayEndMs) {
294	                throw ApiException.unprocessable("SEGMENT_CROSSES_DAY",
295	                        "片段不得跨业务日: " + input.start() + " ~ " + input.end());
296	            }
297	            String id = input.id() == null || input.id().isBlank()
298	                    ? UUID.randomUUID().toString() : input.id();
299	            segments.add(new ValidatedSegment(id, input.assetId(), startMs, endMs));
300	        }
301	
302	        List<ValidatedSegment> sorted = segments.stream()
303	                .sorted(Comparator.comparingLong(ValidatedSegment::startMs)
304	                        .thenComparing(ValidatedSegment::id))
305	                .toList();
306	        for (int i = 1; i < sorted.size(); i++) {
307	            if (sorted.get(i).startMs() < sorted.get(i - 1).endMs()) {
308	                throw ApiException.unprocessable("SEGMENT_OVERLAP",
309	                        "片段时间重叠: " + sorted.get(i - 1).id() + " 与 " + sorted.get(i).id());
310	            }
311	        }
312	
313	        for (ValidatedSegment segment : segments) {
314	            if (repo.findAsset(segment.assetId()).isEmpty()) {
315	                throw ApiException.notFound("素材不存在: " + segment.assetId());
316	            }
317	            List<GrantRow> covering = repo.findCoveringGrants(channelId, segment.assetId(),
318	                    segment.startMs(), segment.endMs());
319	            if (covering.isEmpty()) {
320	                throw ApiException.unprocessable("NO_COVERING_GRANT",
321	                        "片段未被单条有效授权完整覆盖: " + segment.id());
322	            }
323	        }
324	        return segments;
325	    }
326	
327	    /** 发布时加行锁选取覆盖授权；不存在或未撤销的覆盖授权时 422 拒绝整次发布。 */
328	    private GrantRow selectCoveringGrantForUpdate(String channelId, SegmentRow segment) {
329	        List<GrantRow> candidates = repo.findCoveringGrantsForUpdate(channelId, segment.assetId(),
330	                segment.startMs(), segment.endMs());
331	        return candidates.stream()
332	                .filter(grant -> !grant.revoked())
333	                .findFirst()
334	                .orElseThrow(() -> ApiException.unprocessable("GRANT_INVALID",
335	                        "片段授权已失效，发布拒绝: " + segment.id()));
336	    }
337	
338	    /**
339	     * 幂等执行：去重记录与业务结果同事务提交；同 requestId 同参数返回原结果，
340	     * 同 requestId 不同参数返回 409；业务失败抛异常回滚，不占用 requestId。
341	     */
342	    private <T> T idempotent(String requestId, String operation, String paramsHash,
343	                             Class<T> type, Supplier<T> action) {
344	        if (requestId == null || requestId.isBlank()) {
345	            throw ApiException.badRequest("requestId 不能为空");
346	        }
347	        Optional<RequestRow> existing = repo.findRequestForUpdate(requestId);
348	        if (existing.isPresent()) {
349	            return replay(existing.get(), operation, paramsHash, type);
350	        }
351	        try {
352	            repo.insertRequest(requestId, operation, paramsHash, nowMs());
353	        } catch (DuplicateKeyException e) {
354	            // 并发同 requestId：等待对方事务结束后读取已提交记录
355	            RequestRow committed = repo.findRequestForUpdate(requestId)
356	                    .orElseThrow(() -> ApiException.conflict("REQUEST_ID_CONFLICT",
357	                            "requestId 并发冲突: " + requestId));
358	            return replay(committed, operation, paramsHash, type);
359	        }
360	        T result = action.get();
361	        try {
362	            repo.completeRequest(requestId, objectMapper.writeValueAsString(result));
363	        } catch (Exception e) {
364	            throw new IllegalStateException("幂等结果序列化失败", e);
365	        }
366	        return result;
367	    }
