                .andExpect(status().isOk());

        // 重复 overrideKey（任意参数）：409
        postJson("/api/emergency-overrides", overrideBody("req-" + s.p + "dup", s.p + "A",
                        s.channel, s.a, s.ga, 6, T_10, T_10_20))
                .andExpect(status().isConflict())
