        mvc.perform(post("/api/assets").contentType(MediaType.APPLICATION_JSON)
                        .content(Map.of("id", p + "fb", "durationMs", 30000)
                                .toString().replace("=", "\":\"").replace(", ", "\",\"")
                                .replace("{", "{\"").replace("}", "\"}")))
                .andExpect(status().isOk());

